using Nakama.Api.BuildingBlocks.Time;namespace Nakama.Api.Modules.Tasks.Domain;public sealed class TaskDependency{private TaskDependency(){}private TaskDependency(Guid task,Guid depends,Guid user,DateTimeOffset at){if(task==Guid.Empty||depends==Guid.Empty||user==Guid.Empty||task==depends)throw new ArgumentException("Invalid dependency.");Id=Guid.NewGuid();TaskId=task;DependsOnTaskId=depends;CreatedByUserId=user;CreatedAt=at;}public Guid Id{get;private set;}public Guid TaskId{get;private set;}public Guid DependsOnTaskId{get;private set;}public Guid CreatedByUserId{get;private set;}public DateTimeOffset CreatedAt{get;private set;}public static TaskDependency Create(Guid task,Guid depends,Guid user,IClock c)=>new(task,depends,user,c.UtcNow);}
